     * `summarise_book` carries on from there.
     */
    fun `bookRun`(`id`: kotlin.ULong): BookRunProgress?
    
    /**
     * The saved whole-book summary, with every saved chapter summary.
     */
    fun `bookSynopsis`(`id`: kotlin.ULong): BookSynopsis?
    
    /**
