/**
 * Every error the API returns. `reason` fields are diagnostics for logs and
 * detail text; the host writes its own headline per case. (Fields avoid the
 * name `message`, which clashes with Kotlin's `Throwable.message`.)
 */
sealed class LibraryException: kotlin.Exception() {
    
    /**
     * The form or request is not acceptable; `reason` says which field.
     */
    class InvalidInput(
        
        val `reason`: kotlin.String
        ) : LibraryException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * The book form was refused: each entry names a `BookInput` field and
     * says what to fix, so the form shows it under that field.
     */
    class InvalidFields(
        
        val `fields`: List<FieldError>
        ) : LibraryException() {
        override val message
            get() = "fields=${ `fields` }"
    }
    
    class NotFound(
        
        val `id`: kotlin.ULong
        ) : LibraryException() {
        override val message
            get() = "id=${ `id` }"
    }
    
    /**
     * That book is already in the library (importing the same catalogue
     * work or EPUB twice).
     */
    class AlreadyInLibrary(
        
        val `id`: kotlin.ULong
        ) : LibraryException() {
        override val message
            get() = "id=${ `id` }"
    }
    
    /**
     * The library file could not be read or written. Nothing in memory
     * changed; the file on disk is left as it was.
     */
    class Storage(
        
        val `reason`: kotlin.String
        ) : LibraryException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * The library on disk was written by a newer version of the app.
     */
    class NewerLibrary(
        
        val `found`: kotlin.UInt, 
        
        val `supported`: kotlin.UInt
        ) : LibraryException() {
        override val message
            get() = "found=${ `found` }, supported=${ `supported` }"
    }
    
    /**
     * The online catalogue is switched off in Settings.
     */
    class CatalogueDisabled(
        ) : LibraryException() {
        override val message
            get() = ""
    }
    
    /**
     * No connection, DNS failure, or connection refused.
     */
    class Offline(
        
        val `reason`: kotlin.String
        ) : LibraryException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class Timeout(
        ) : LibraryException() {
        override val message
            get() = ""
    }
    
    /**
     * The catalogue answered, but not usefully (5xx, 429, maintenance).
     */
    class CatalogueUnavailable(
        
        val `reason`: kotlin.String
        ) : LibraryException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * The catalogue's answer could not be understood.
     */
    class BadResponse(
        
        val `reason`: kotlin.String
        ) : LibraryException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * The server's TLS certificate was rejected.
     */
    class Certificate(
        
        val `reason`: kotlin.String
        ) : LibraryException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * Any other network failure.
     */
    class Network(
        
        val `reason`: kotlin.String
        ) : LibraryException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * The file is not an EPUB this app can read.
     */
    class UnsupportedFile(
        
        val `reason`: kotlin.String
        ) : LibraryException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * The book has no saved EPUB to read (typed in, from the catalogue, or
     * imported before Pocket Library kept EPUBs), or the saved one is gone.
     */
    class NotReadable(
        
        val `reason`: kotlin.String
        ) : LibraryException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * The request was stopped with its `Cancellation`. Nothing changed.
     */
    class Cancelled(
        ) : LibraryException() {
        override val message
            get() = ""
    }
    
    /**
     * The app went to the background and the work was stopped. Nothing
     * changed; it is safe to try again on return.
     */
    class Interrupted(
        ) : LibraryException() {
        override val message
            get() = ""
    }
    
    /**
     * `shutdown()` was called; the instance accepts no more work.
     */
    class ShutDown(
        ) : LibraryException() {
        override val message
            get() = ""
    }
    
    /**
     * The on-device model can't run now; `reason` says why in words the
     * reader can act on ("Turn on Apple Intelligence in Settings").
     */
    class SummaryUnavailable(
        
        val `reason`: kotlin.String
        ) : LibraryException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * The model's safety rules declined the chapter.
     */
    class SummaryRefused(
        
        val `reason`: kotlin.String
        ) : LibraryException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * The model failed some other way. Trying again may work.
     */
    class SummaryFailed(
        
        val `reason`: kotlin.String
        ) : LibraryException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * Another copy of the library core has this library open.
     */
    class InUse(
        
        val `reason`: kotlin.String
        ) : LibraryException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<LibraryException> {
        override fun lift(error_buf: RustBuffer.ByValue): LibraryException = FfiConverterTypeLibraryError.lift(error_buf)
    }

    
}

